-- Google Drive task proposal batches generated by UNI (UNI-2181, spec §6.5, ADR 0010, ADR 0047).
-- Holds normalized proposal items until converted or discarded (items set to NULL on both).
-- No FOREIGN KEY (migration lint).
CREATE TABLE drive_task_proposals (
  id                 TEXT PRIMARY KEY,
  organization_id    TEXT NOT NULL,
  workspace_id       TEXT NOT NULL,
  drive_file_id      TEXT NOT NULL,
  connection_id      TEXT NOT NULL,
  requested_by       TEXT NOT NULL,
  requested_by_kind  TEXT NOT NULL DEFAULT 'human',
  prompt             TEXT NOT NULL DEFAULT '',
  project_id         TEXT,
  parent_task_id     TEXT,
  context_task_id    TEXT,
  items              JSONB,
  truncated          BOOLEAN NOT NULL DEFAULT false,
  usage_event_id     TEXT NOT NULL DEFAULT '',
  status             TEXT NOT NULL DEFAULT 'ready',
  status_changed_at  TIMESTAMPTZ,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at         TIMESTAMPTZ NOT NULL DEFAULT (now() + interval '7 days'),

  CONSTRAINT drive_task_proposals_ids_nonempty
    CHECK (
      id <> ''
      AND organization_id <> ''
      AND workspace_id <> ''
      AND drive_file_id <> ''
      AND connection_id <> ''
      AND requested_by <> ''
    ),
  CONSTRAINT drive_task_proposals_requested_by_kind_check
    CHECK (requested_by_kind IN ('human')),
  CONSTRAINT drive_task_proposals_status_check
    CHECK (status IN ('ready', 'converted', 'discarded'))
);
